const deleteOldestOwnWrite = `-- name: DeleteOldestOwnWrite :execrows
DELETE FROM own_writes
WHERE id = (
    SELECT o.id FROM own_writes o
    WHERE o.repository = ?1 AND o.number = ?2
      AND o.field = ?3
      AND json_extract(o.metadata, '$.label') = CAST(?4 AS TEXT)
      AND json_extract(o.metadata, '$.change') = CAST(?5 AS TEXT)
    ORDER BY o.id LIMIT 1
)
`

type DeleteOldestOwnWriteParams struct {
	Repository string
	Number     int64
	Field      string
	Label      string
	Change     string
}

func (q *Queries) DeleteOldestOwnWrite(ctx context.Context, arg DeleteOldestOwnWriteParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, deleteOldestOwnWrite,
		arg.Repository,
		arg.Number,
		arg.Field,
		arg.Label,
		arg.Change,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const deleteOldestTreeOwnWrite = `-- name: DeleteOldestTreeOwnWrite :execrows
DELETE FROM own_writes
WHERE id = (
    SELECT o.id FROM own_writes o
    WHERE o.repository = ?1 AND o.number = ?2
      AND o.field = ?3
      AND json_extract(o.metadata, '$.change') = CAST(?4 AS TEXT)
      AND (
          (o.field = 'parent'
           AND lower(json_extract(o.metadata, '$.parent_repository')) = lower(CAST(?5 AS TEXT))
           AND json_extract(o.metadata, '$.parent') = CAST(?6 AS INTEGER))
          OR (o.field = 'blockers'
              AND lower(json_extract(o.metadata, '$.blocker_repository')) = lower(CAST(?5 AS TEXT))
              AND json_extract(o.metadata, '$.blocker') = CAST(?6 AS INTEGER))
      )
    ORDER BY o.id LIMIT 1
)
`

type DeleteOldestTreeOwnWriteParams struct {
	Repository      string
	Number          int64
	Field           string
	Change          string
	OtherRepository string
	OtherNumber     int64
}

func (q *Queries) DeleteOldestTreeOwnWrite(ctx context.Context, arg DeleteOldestTreeOwnWriteParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, deleteOldestTreeOwnWrite,
		arg.Repository,
		arg.Number,
		arg.Field,
		arg.Change,
		arg.OtherRepository,
		arg.OtherNumber,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

