const listWorkstreamsNeedingBuckets = `-- name: ListWorkstreamsNeedingBuckets :many
SELECT CAST(w.number AS INTEGER) AS number FROM workstreams w
WHERE w.repository = ?1 AND w.state = 'open' AND w.number IS NOT NULL
  AND ((SELECT COUNT(*) FROM issues c
        WHERE c.workstream = w.id AND c.parent IS NULL AND json_extract(c.metadata, '$.github.bucket') IS NULL)
       + (SELECT COUNT(*) FROM json_each(w.metadata, '$.github.buckets'))
       + (SELECT COUNT(*) FROM json_each(w.metadata, '$.github.nested')) > CAST(?2 AS INTEGER)
       OR EXISTS (
           SELECT 1 FROM json_each(w.metadata, '$.github.buckets') b
           WHERE json_extract(b.value, '$.state') = 'open'
             AND (NOT EXISTS (SELECT 1 FROM issues c
                              WHERE c.workstream = w.id AND json_extract(c.metadata, '$.github.bucket') = json_extract(b.value, '$.number'))
                  OR EXISTS (SELECT 1 FROM issues c
                             WHERE c.workstream = w.id AND json_extract(c.metadata, '$.github.bucket') = json_extract(b.value, '$.number')
                               AND c.state = 'closed'))))
ORDER BY w.number
`

type ListWorkstreamsNeedingBucketsParams struct {
	Repository string
	Maximum    int64
}

// A Workstream needs buckets when it has more than the maximum of direct sub-issues, or when an open bucket has no
// sub-issues or holds a closed issue.
func (q *Queries) ListWorkstreamsNeedingBuckets(ctx context.Context, arg ListWorkstreamsNeedingBucketsParams) ([]int64, error) {
	rows, err := q.db.QueryContext(ctx, listWorkstreamsNeedingBuckets, arg.Repository, arg.Maximum)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var number int64
		if err := rows.Scan(&number); err != nil {
			return nil, err
		}
		items = append(items, number)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

